// build-sectors.mjs — turns the Round 9 sector research
// (docs/studio/research-2026-11/sectors-*.md, JSON blocks) into
//   src/server/studio/sectors/data.generated.ts  (server-only, full playbooks)
//   src/lib/studio/sectors/kinds.generated.ts    (browser-safe: id, kind, match)
// Never hand-edit the generated files; edit the research and run
//   node scripts/sectors/build-sectors.mjs
import { readFileSync, writeFileSync } from "node:fs";

const FILES = [
  "sectors-products-a",
  "sectors-products-b",
  "sectors-services-a",
  "sectors-services-b",
];
const KINDS = new Set(["product", "service", "hybrid", "venue", "digital"]);
const LIMITS = { show: 200, wants: 140, doubts: 140, videoArc: 220, regulated: 120 };

// Match terms too generic to name a sector alone, and per-sector fixes found
// against the benchmark brands (a "tools" mention made an AI company a hardware store).
const GENERIC = new Set([
  "tools",
  "paint",
  "app",
  "apps",
  "design",
  "services",
  "online",
  "store",
  "shop",
  "products",
]);
const DROP = { "hardware-building-supplies": ["plumbing", "electrical"] };
const EXTRA = { "real-estate-agent": ["real estate"], cafe: ["tea stall", "chai"] };

const sectors = [];
for (const name of FILES) {
  const md = readFileSync(`docs/studio/research-2026-11/${name}.md`, "utf8");
  for (const m of md.matchAll(/```json\s*([\s\S]*?)```/g)) {
    let s;
    try {
      s = JSON.parse(m[1]);
    } catch {
      continue;
    }
    if (!s || typeof s.id !== "string") continue;
    if (!KINDS.has(s.kind)) throw new Error(`${s.id}: bad kind ${s.kind}`);
    for (const [k, max] of Object.entries(LIMITS))
      if (s[k] && String(s[k]).length > max) s[k] = String(s[k]).slice(0, max);
    sectors.push({
      id: s.id,
      label: s.label,
      kind: s.kind,
      parent: s.parent,
      match: [...(s.match ?? []).map((x) => String(x).toLowerCase()), ...(EXTRA[s.id] ?? [])]
        .filter((t) => !GENERIC.has(t) && !(DROP[s.id] ?? []).includes(t))
        .slice(0, 14),
      show: s.show,
      proof: (s.proof ?? []).slice(0, 5),
      wants: s.wants,
      doubts: s.doubts,
      cliches: (s.cliches ?? []).slice(0, 3),
      angles: (s.angles ?? []).slice(0, 4),
      carousels: (s.carousels ?? []).slice(0, 3),
      videoArc: s.videoArc,
      typeVoices: (s.typeVoices ?? []).slice(0, 3),
      moments: (s.moments ?? []).slice(0, 6),
      ...(s.regulated ? { regulated: s.regulated } : {}),
    });
  }
}
const ids = new Set();
for (const s of sectors) {
  if (ids.has(s.id)) throw new Error(`duplicate sector ${s.id}`);
  ids.add(s.id);
}
sectors.sort((a, b) => a.id.localeCompare(b.id));

const head = (what) =>
  `// GENERATED by scripts/sectors/build-sectors.mjs from docs/studio/research-2026-11.\n// ${what} Never hand-edit; ids are stored: add, never rename.\n`;
writeFileSync(
  "src/server/studio/sectors/data.generated.ts",
  `${head("Full sector playbooks (server-only).")}import "server-only";\nimport type { SectorPlaybook } from "./types";\n\nexport const SECTOR_PLAYBOOKS: readonly SectorPlaybook[] = ${JSON.stringify(sectors, null, 2)};\n`,
);
writeFileSync(
  "src/lib/studio/sectors/kinds.generated.ts",
  `${head("Browser-safe sector ids, kinds and match terms.")}import type { SectorKindRow } from "./kinds";\n\nexport const SECTOR_KINDS: readonly SectorKindRow[] = ${JSON.stringify(
    sectors.map((s) => ({ id: s.id, kind: s.kind, parent: s.parent, match: s.match })),
  )};\n`,
);
console.log(`${sectors.length} sectors`);
